use provisional_recovery_reducer::*;
fn cursor(seq:u64)->Cursor {Cursor{domain:Domain{store:"A".into(),scope:"S".into(),stream:"X".into()},seq}}
fn state()->State {State::new(cursor(10),"old".into(),"E2".into(),2)}
fn event(seq:u64,body:&str)->Event {Event{cursor:cursor(seq),payload:body.into()}}
fn identity(intent:&str)->Identity {Identity{intent:intent.into(),action:"rename".into(),attempt:"attempt1".into(),scope:"S".into(),parameters:"supplier-U/name-B".into()}}
fn receipt()->Receipt {Receipt{id:"receipt-real-lab".into(),identity:identity("original"),effect:"committed-rev2".into()}}
#[test] fn applies_payload_but_waits_for_commit(){let mut s=state();assert_eq!(s.receive(event(11,"new")),Outcome::Applied);assert_eq!(s.projection,"new");assert_eq!(s.applied.seq,11);assert_eq!(s.committed.seq,10);assert_eq!(s.committed_projection,"old");s.commit();assert_eq!(s.committed.seq,11);assert_eq!(s.committed_projection,"new");}
#[test] fn duplicate_same_four_fields_does_not_apply(){let mut s=state();s.receive(event(11,"new"));assert_eq!(s.receive(event(11,"new")),Outcome::Duplicate);assert_eq!(s.applied.seq,11);}
#[test] fn all_three_domain_fields_are_required(){for field in 0..3 {let mut s=state();let mut e=event(999,"foreign");match field {0=>e.cursor.domain.store="B".into(),1=>e.cursor.domain.scope="T".into(),_=>e.cursor.domain.stream="Y".into()};assert_eq!(s.receive(e),Outcome::WrongDomain);assert_eq!(s.received.seq,10);assert!(s.buffered.is_empty());}}
#[test] fn same_identity_different_payload_is_conflict(){let mut s=state();s.receive(event(11,"first"));assert_eq!(s.receive(event(11,"other")),Outcome::Conflict);assert_eq!(s.projection,"first");}
#[test] fn gap_pulls_from_committed_boundary(){let mut s=state();s.receive(event(11,"volatile"));assert_eq!(s.receive(event(13,"later")),Outcome::Pull(cursor(10)));assert_eq!(s.committed.seq,10);assert_eq!(s.applied.seq,11);assert_eq!(s.received.seq,13);}
#[test] fn buffer_is_bounded_and_overflow_requests_snapshot(){let mut s=state();s.receive(event(13,"a"));s.receive(event(14,"b"));assert_eq!(s.receive(event(15,"c")),Outcome::SnapshotRequired);assert_eq!(s.buffered.len(),2);assert_eq!(s.receive(event(11,"blocked")),Outcome::SnapshotRequired);assert_eq!(s.applied.seq,10);}
#[test] fn filling_gap_drains_in_order_without_early_commit(){let mut s=state();s.receive(event(12,"twelve"));assert_eq!(s.receive(event(11,"eleven")),Outcome::Applied);assert_eq!(s.applied.seq,12);assert_eq!(s.projection,"twelve");assert!(s.buffered.is_empty());assert_eq!(s.committed.seq,10);}
#[test] fn buffered_identity_conflict_is_detected(){let mut s=state();s.receive(event(13,"first"));assert_eq!(s.receive(event(13,"changed")),Outcome::Conflict);assert_eq!(s.buffered.get(&13).unwrap().payload,"first");}
#[test] fn epoch_is_only_display_fence(){let mut s=state();let r=receipt();s.receipts.insert(r.id.clone(),r.clone());assert_eq!(s.display_callback("E1","stale"),Outcome::StaleDisplay);assert_eq!(s.display_callback("E2","current"),Outcome::Displayed);s.reconnect("E0".into());assert_eq!(s.committed.seq,10);assert_eq!(s.receipts.get(&r.id),Some(&r));assert_eq!(s.display,"current");}
#[test] fn old_epoch_effect_is_verified_by_exact_ledger_equality(){let mut s=state();let r=receipt();assert_eq!(s.reconcile(&r.identity,&r,std::slice::from_ref(&r)),Outcome::Verified);assert_eq!(s.receipts.get(&r.id),Some(&r));assert!(s.display.is_empty());}
#[test] fn receipt_must_match_every_original_identity_field(){let r=receipt();for field in 0..5 {let mut s=state();let mut wrong=r.identity.clone();match field {0=>wrong.intent="different".into(),1=>wrong.action="different".into(),2=>wrong.attempt="different".into(),3=>wrong.scope="different".into(),_=>wrong.parameters="different".into()};assert_eq!(s.reconcile(&wrong,&r,std::slice::from_ref(&r)),Outcome::Unverified);assert!(s.receipts.is_empty());}}
#[test] fn hint_is_not_receipt_and_forged_effect_is_rejected(){let mut s=state();let r=receipt();assert_eq!(s.reconcile(&r.identity,&r,&[]),Outcome::Unverified);let mut forged=r.clone();forged.effect="fabricated".into();assert_eq!(s.reconcile(&r.identity,&forged,&[r.clone()]),Outcome::Unverified);assert!(s.receipts.is_empty());}
#[test] fn unknown_survives_reconnect_and_new_intent(){let mut s=state();let old=identity("original");s.unknown.insert(old.intent.clone(),old.clone());s.reconnect("E3".into());assert_eq!(s.unknown.get("original"),Some(&old));assert!(s.synthetic_intents.is_empty());assert_eq!(s.user_new_intent("original",identity("new"),Some("synthetic-user-instruction")),Outcome::NewIntent);assert_eq!(s.unknown.get("original"),Some(&old));assert_eq!(s.synthetic_intents.len(),1);}
#[test] fn untrusted_or_duplicate_new_intent_is_rejected(){let mut s=state();s.unknown.insert("original".into(),identity("original"));assert_eq!(s.user_new_intent("original",identity("new"),None),Outcome::Rejected);assert_eq!(s.user_new_intent("original",identity("original"),Some("user")),Outcome::Rejected);assert_eq!(s.user_new_intent("missing",identity("new"),Some("user")),Outcome::Rejected);assert!(s.synthetic_intents.is_empty());}
#[test] fn zero_budget_cannot_buffer_gap(){let mut s=state();s.limit=0;assert_eq!(s.receive(event(12,"gap")),Outcome::SnapshotRequired);assert!(s.buffered.is_empty());}
#[test] fn reconnect_replays_uncommitted_payload_from_checkpoint(){let mut s=state();s.receive(event(11,"volatile"));s.receive(event(13,"gap"));s.reconnect("E3".into());assert_eq!(s.applied.seq,10);assert_eq!(s.received.seq,10);assert_eq!(s.projection,"old");assert!(s.buffered.is_empty());assert_eq!(s.receive(event(11,"volatile")),Outcome::Applied);assert_eq!(s.committed.seq,10);}
#[test] fn conflicting_receipt_id_cannot_overwrite_known_effect(){let mut s=state();let r=receipt();s.reconcile(&r.identity,&r,std::slice::from_ref(&r));let mut other=r.clone();other.effect="changed".into();assert_eq!(s.reconcile(&other.identity,&other,std::slice::from_ref(&other)),Outcome::Unverified);assert_eq!(s.receipts.get(&r.id),Some(&r));}
#[test] fn new_intent_must_keep_unknown_relation_scope_and_parameters(){for field in 0..3 {let mut s=state();s.unknown.insert("original".into(),identity("original"));let mut n=identity("new");match field {0=>n.scope="T".into(),1=>n.action="delete".into(),_=>n.parameters="changed".into()};assert_eq!(s.user_new_intent("original",n,Some("user")),Outcome::Rejected);assert!(s.synthetic_intents.is_empty());}}
#[test] fn repeated_user_instruction_does_not_duplicate_new_intent(){let mut s=state();s.unknown.insert("original".into(),identity("original"));assert_eq!(s.user_new_intent("original",identity("new"),Some("user")),Outcome::NewIntent);assert_eq!(s.user_new_intent("original",identity("new"),Some("user")),Outcome::Rejected);assert_eq!(s.synthetic_intents.len(),1);}
